import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

test('does not use process-local authority', async () => {
  const source = await readFile(new URL('../src/cache/client.ts', import.meta.url), 'utf8');
  assert.doesNotMatch(source, /new Map/);
  assert.match(source, /redis\.get/);
});
